Console.WriteLine("PASS background material and clock format persist independently per display");
groups.SelectedItem="Rendimiento";Avalonia.Threading.Dispatcher.UIThread.RunJobs();var graphics=window.GetVisualDescendants().OfType<ComboBox>().First(x=>x.ItemsSource!.Cast<object>().Contains("Vulkan"));graphics.SelectedItem="Vulkan";Avalonia.Threading.Dispatcher.UIThread.RunJobs();if(root.WindowsRenderer!="Vulkan"||new Settings(id).WindowsRenderer!="Vulkan"||right.WindowsRenderer!="Automático")throw new Exception("Graphics choice must persist globally even while editing one display");var apply=window.GetVisualDescendants().OfType<Button>().First(b=>b.Content?.ToString()=="Aplicar y reiniciar");apply.RaiseEvent(new Avalonia.Interactivity.RoutedEventArgs(Button.ClickEvent));if(restarts!=1)throw new Exception("Graphics restart was not requested");Console.WriteLine("PASS graphics selection persists globally; restart is explicit");
groups.SelectedItem="Inicio";Avalonia.Threading.Dispatcher.UIThread.RunJobs();var start=window.GetVisualDescendants().OfType<CheckBox>().First(x=>x.Content?.ToString()=="Abrir WirePulse al iniciar sesión");start.IsChecked=true;if(!root.StartupAsked||!File.Exists(Path.Combine(startupFolder,"wirepulse.desktop")))throw new Exception("Startup settings did not enable consented registration");start.IsChecked=false;if(File.Exists(Path.Combine(startupFolder,"wirepulse.desktop")))throw new Exception("Startup settings did not remove registration");Directory.Delete(startupFolder,true);Console.WriteLine("PASS startup settings enable/disable without changing this computer's login items");
int decision=-1;var consent=new StartupPrompt(value=>{decision=value?1:0;return null;});consent.Show();Avalonia.Threading.Dispatcher.UIThread.RunJobs();var no=consent.GetVisualDescendants().OfType<Button>().First(b=>b.Content?.ToString()=="Ahora no");no.RaiseEvent(new Avalonia.Interactivity.RoutedEventArgs(Button.ClickEvent));if(decision!=0||consent.IsVisible)throw new Exception("Decline did not close startup prompt without enabling it");Console.WriteLine("PASS startup dialog honours decline");
window.Close();
foreach(var key in new[]{id,id+"left",id+"right"}){var hash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(key)))[..16];File.Delete(Path.Combine(Settings.Folder,"display-"+hash+".json"));}

// Exercise actual pointer routing, rather than reproducing the editor's drag calculations.
var scene=new SceneDocument{Items=[new SceneItem{Kind="image",X=.1,Y=.1,Width=.2,Height=.2,KeepAspect=false}]};
var canvas=new EditorCanvas(()=>scene){Snapping=false};var editorHost=new Window{Width=1000,Height=600,Content=canvas};editorHost.Show();Avalonia.Threading.Dispatcher.UIThread.RunJobs();
var dragStart=scene.Items[0].Bounds(canvas.Bounds.Size).Center;editorHost.MouseDown(dragStart,Avalonia.Input.MouseButton.Left);editorHost.MouseMove(dragStart+new Vector(75,40));editorHost.MouseUp(dragStart+new Vector(75,40),Avalonia.Input.MouseButton.Left);Avalonia.Threading.Dispatcher.UIThread.RunJobs();
var moved=scene.Items[0].Bounds(canvas.Bounds.Size);if(Math.Abs(moved.X-175)>1||Math.Abs(moved.Y-100)>1)throw new Exception("Pointer drag did not move image independently");
var handle=moved.BottomRight;editorHost.MouseDown(handle,Avalonia.Input.MouseButton.Left);editorHost.MouseMove(handle+new Vector(50,30));editorHost.MouseUp(handle+new Vector(50,30),Avalonia.Input.MouseButton.Left);Avalonia.Threading.Dispatcher.UIThread.RunJobs();if(Math.Abs(scene.Items[0].Bounds(canvas.Bounds.Size).Width-250)>1)throw new Exception("Pointer resize failed");
var before=scene.Items[0].Clone();scene.Items[0].Locked=true;editorHost.MouseDown(moved.Center,Avalonia.Input.MouseButton.Left);editorHost.MouseMove(moved.Center+new Vector(100,100));editorHost.MouseUp(moved.Center+new Vector(100,100),Avalonia.Input.MouseButton.Left);if(scene.Items[0].X!=before.X)throw new Exception("Locked image moved");editorHost.Close();
var rect=new Rect(390,100,200,100);var snapped=SceneGeometry.Move(rect,new Vector(7,0),new Size(1000,600),[],true);var free=SceneGeometry.Move(rect,new Vector(7,0),new Size(1000,600),[],false);if(snapped.Rect.Center.X!=500||free.Rect.X!=397)throw new Exception("Optional screen-center snapping failed");Console.WriteLine("PASS actual pointer drag/resize, locked objects and optional snapping");
var preview=right.Preview();preview.Scene=SceneDocument.Migrate(right,new Size(1920,1080));var originalX=right.N("sphereX");preview.Scene.Items[1].X=.2;preview.Set("sphereX",3d);if(right.Scene!=null||right.N("sphereX")!=originalX)throw new Exception("Draft edited original preferences");var duplicate=preview.Scene.Items[1].Clone();duplicate.Style["wirecolor"]=System.Text.Json.Nodes.JsonValue.Create("#00ff00");if(preview.Scene.Items[1].Style["wirecolor"]?.ToString()=="#00ff00")throw new Exception("Duplicate shares mutable style");Console.WriteLine("PASS legacy migration, cancelled draft isolation and deep-copy object styles");
var fixture=Path.Combine(AppContext.BaseDirectory,"fixtures","disposal.gif");using(var image=new ImageFrames(fixture)){if(!image.Animated)throw new Exception("GIF was decoded as a static image");using var bitmap=new SkiaSharp.SKBitmap(16,16);using var drawing=new SkiaSharp.SKCanvas(bitmap);SkiaSharp.SKColor Pixel(int x){drawing.Clear(SkiaSharp.SKColors.Transparent);image.Draw(drawing,new SkiaSharp.SKRect(0,0,16,16));return bitmap.GetPixel(x,8);}if(Pixel(12).Red<200)throw new Exception("GIF first frame incorrect");image.Update(.11,false);if(Pixel(12).Blue<200||Pixel(2).Alpha!=0)throw new Exception("GIF disposal/transparency incorrect");image.Update(.11,true);if(Pixel(12).Blue<200)throw new Exception("Paused GIF advanced");image.Update(.11,false);if(Pixel(12).Green<200)throw new Exception("GIF third frame incorrect");image.Update(.11,false);if(Pixel(12).Red<200)throw new Exception("GIF loop incorrect");}Console.WriteLine("PASS animated GIF frames, transparency disposal, pause and looping");
var testSettings=root.Preview();testSettings.Scene=new SceneDocument{Items=[new SceneItem{Kind="text",Name="Texto de prueba",Text="Hola",X=.1,Y=.1,Width=.2,Height=.2}]};var editWindow=new EditorWindow(testSettings,new Spectrum(),new MediaService(root),new PixelRect(0,0,1000,600),1,"Fixture");editWindow.Show();Avalonia.Threading.Dispatcher.UIThread.RunJobs();if(snapshots){using var shot=new Avalonia.Media.Imaging.RenderTargetBitmap(new PixelSize(1000,600));shot.Render(editWindow);shot.Save("canvas-editor.png");}var editCanvas=editWindow.GetVisualDescendants().OfType<EditorCanvas>().Single();editCanvas.SelectedId=testSettings.Scene.Items[0].Id;editWindow.Select(editCanvas.SelectedId);void Click(Window owner,string label){var button=owner.GetVisualDescendants().OfType<Button>().First(b=>b.Content?.ToString()==label);button.RaiseEvent(new Avalonia.Interactivity.RoutedEventArgs(Button.ClickEvent));Avalonia.Threading.Dispatcher.UIThread.RunJobs();}
Click(editWindow,"Duplicar");if(testSettings.Scene.Items.Count!=1)throw new Exception("Draft duplicate changed saved scene before Save");Click(editWindow,"↶ Deshacer");Click(editWindow,"↷ Rehacer");Click(editWindow,"Guardar diseño");if(editWindow.IsVisible||testSettings.Scene.Items.Count!=2||testSettings.Scene.Items[0].Id==testSettings.Scene.Items[1].Id)throw new Exception("Editor save/undo/redo/duplicate failed");Console.WriteLine("PASS complete editor duplicate, undo, redo and explicit Save");
var ownerWindow=new Window();ownerWindow.Show();var cancelled=ColorDialog.Show(ownerWindow,Avalonia.Media.Colors.Red);Avalonia.Threading.Dispatcher.UIThread.RunJobs();var colorWindow=ownerWindow.OwnedWindows.Single();var colorPicker=colorWindow.GetVisualDescendants().OfType<ColorView>().Single();colorPicker.Color=Avalonia.Media.Colors.Blue;Click(colorWindow,"Cancelar");if(cancelled.GetAwaiter().GetResult()!=null)throw new Exception("Cancelled color dialog applied color");var applied=ColorDialog.Show(ownerWindow,Avalonia.Media.Colors.Red);Avalonia.Threading.Dispatcher.UIThread.RunJobs();colorWindow=ownerWindow.OwnedWindows.Single();colorWindow.GetVisualDescendants().OfType<ColorView>().Single().Color=Avalonia.Media.Colors.Blue;Click(colorWindow,"Aplicar color");if(applied.GetAwaiter().GetResult()!=Avalonia.Media.Colors.Blue)throw new Exception("Native color picker didn't apply selection");ownerWindow.Close();Console.WriteLine("PASS visual color picker Apply and Cancel");
